import{Q as e,X as t,Y as n,ct as r,ft as i,t as a}from"./chunks/framework.CaFWb3SA.js";var o=JSON.parse(`{"title":"ERB 的内置流程","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ERB_Internal_Process.md","filePath":"reference/ERB_Internal_Process.md"}`),s={name:`reference/ERB_Internal_Process.md`};function c(a,o,s,c,l,u){let d=i(`FlowNav`);return r(),n(`div`,null,[o[0]||=t(`<h1 id="erb-的内置流程" tabindex="-1">ERB 的内置流程 <a class="header-anchor" href="#erb-的内置流程" aria-label="Permalink to “ERB 的内置流程”">​</a></h1><p>Emuera 内部有一套固定的游戏流程。它会在特定时机自动调用名字特定的函数——我们要做的，就是把逻辑填进这些“框架函数”里。教程版见<a href="./../guide/tutorials/System_Flow.html">内置流程</a>，完整的流程图见<a href="./../translation/Flow.html">程序流程</a>。</p><h2 id="引擎自动调用的函数" tabindex="-1">引擎自动调用的函数 <a class="header-anchor" href="#引擎自动调用的函数" aria-label="Permalink to “引擎自动调用的函数”">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>调用时机</th><th>用途</th></tr></thead><tbody><tr><td><code>@SYSTEM_TITLE</code></td><td>CSV 加载完毕、执行 <code>BEGIN TITLE</code> 时</td><td>标题画面</td></tr><tr><td><code>@TITLE_LOADGAME</code></td><td>标准标题画面选择“读取存档”时</td><td>自定义读取画面</td></tr><tr><td><code>@EVENTFIRST</code></td><td>新游戏开始（<code>BEGIN FIRST</code>）时</td><td>初始化、开场</td></tr><tr><td><code>@SHOW_SHOP</code></td><td>进入商店/主循环时</td><td>主界面与操作菜单</td></tr><tr><td><code>@EVENTTRAIN</code></td><td>开始训练时</td><td>训练前的准备</td></tr><tr><td><code>@SHOW_STATUS</code></td><td>需要显示状态时</td><td>状态栏</td></tr><tr><td><code>@SHOW_USERCOM</code></td><td>显示指令菜单时</td><td>列出可选指令</td></tr><tr><td><code>@USERCOM</code></td><td>玩家选择指令后</td><td>处理选择</td></tr><tr><td><code>@EVENTCOM</code></td><td>执行指令时</td><td>指令的具体效果</td></tr><tr><td><code>@EVENTCOMEND</code></td><td>指令结束后</td><td>收尾处理</td></tr><tr><td><code>@EVENTEND</code></td><td>游戏结束时</td><td>结算画面</td></tr><tr><td><code>@SYSTEM_AUTOSAVE</code></td><td>自动保存时</td><td>自定义自动存档内容</td></tr><tr><td><code>@EVENTLOAD</code></td><td>存档读取完毕后</td><td>读档后的处理</td></tr><tr><td><code>@CALLTRAINEND</code></td><td><code>CALLTRAIN</code> 自动执行结束后</td><td>收尾</td></tr></tbody></table><blockquote><p><code>@CALLTRAINEND</code> 不是事件函数，不能多重定义。其余带 <code>EVENT</code> 前缀的多为事件函数，可以定义多个，全部都会被调用。</p></blockquote><h2 id="用-begin-切换流程" tabindex="-1">用 BEGIN 切换流程 <a class="header-anchor" href="#用-begin-切换流程" aria-label="Permalink to “用 BEGIN 切换流程”">​</a></h2><p><code>BEGIN</code> 是推进游戏流程的命令：</p><table tabindex="0"><thead><tr><th>关键字</th><th>含义</th></tr></thead><tbody><tr><td><code>BEGIN FIRST</code></td><td>从头开始</td></tr><tr><td><code>BEGIN TITLE</code></td><td>回到标题画面</td></tr><tr><td><code>BEGIN TRAIN</code></td><td>开始训练</td></tr><tr><td><code>BEGIN AFTERTRAIN</code></td><td>结束训练</td></tr><tr><td><code>BEGIN ABLUP</code></td><td>进入升级界面</td></tr><tr><td><code>BEGIN TURNEND</code></td><td>结束回合</td></tr></tbody></table><p>调用 <code>BEGIN</code> 会终止当前函数的执行，且<strong>不会返回</strong>原来的函数。</p><h2 id="流程概览" tabindex="-1">流程概览 <a class="header-anchor" href="#流程概览" aria-label="Permalink to “流程概览”">​</a></h2><p>下面这张图是交互式的，点击节点即可跳到对应条目：</p>`,11),e(d),o[1]||=t(`<h2 id="最小示例" tabindex="-1">最小示例 <a class="header-anchor" href="#最小示例" aria-label="Permalink to “最小示例”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">; 不定义 @SYSTEM_TITLE，直接使用引擎自带的标题画面</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 欢迎来到我的游戏！</span></span>
<span class="line"><span style="color:#569CD6;">  WAIT</span></span>
<span class="line"><span style="color:#C586C0;">  BEGIN</span><span style="color:#9CDCFE;"> TITLE</span></span></code></pre></div><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../guide/tutorials/System_Flow.html">内置流程</a>（教程）</li><li><a href="./../translation/Flow.html">程序流程</a></li><li><a href="./../translation/Function_and_Preprocessor.html">函数与预处理指令</a></li><li><a href="./ERB_Compound_Statements.html">ERB 的复合语句</a></li></ul>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};